/* Portable visual page router. Accounts, media, verification and checkout are demonstrations. */
const pageMain = document.querySelector('main');
const homeTemplate = pageMain.innerHTML;
const pageNotice = '<p class="page-notice">DESIGN PREVIEW · Sample content and prices. No accounts, payments or broadcasts are connected.</p>';
const pageTitles = {home:'Home',collection:'The Collection',live:'Live Lounge',membership:'Membership',library:'My Library',account:'My Account','manage-membership':'Membership Management',signin:'Sign In',signup:'Create Account',checkout:'Checkout Preview',confirmation:'Confirmation Preview',verify:'Age Verification',about:'About Jamie',privacy:'Privacy',terms:'Terms',support:'Support'};
const escapeText = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const action = (label,href) => `<a class="button platinum" href="#/${href}">${label} <span aria-hidden="true">›</span></a>`;
function pageHeading(kicker,title,copy){return `<div class="page-heading"><p class="eyebrow">${kicker}</p><h1>${title}</h1>${copy?`<p class="intro">${copy}</p>`:''}</div>`;}
function catalogCard(c){return `<article><a href="#/release/${c.id}" aria-label="View ${c.title}">${art(c)}</a><h3 class="collection-title"><a href="#/release/${c.id}">${c.title}</a></h3><p class="card-meta">${c.detail}</p><div class="card-bottom"><strong>${c.price===null?'Member collection':`$${c.price} · Sample price`}</strong><a class="text-link" href="#/release/${c.id}">View collection ›</a></div></article>`;}
function catalog(){return `${pageHeading('CURATED FOR YOUR EVENINGS','The private collection.','Films, photographs, and personal chapters. Find your kind of evening.')}<div class="catalog-tools"><div class="filters" aria-label="Collection categories">${[['all','All collections'],['film','Films'],['photos','Photo sets'],['member','For members']].map(([id,label])=>`<button data-catalog-filter="${id}" aria-pressed="${id==='all'}" class="${id==='all'?'active':''}">${label}</button>`).join('')}</div><label class="search-label">Find a collection<input id="catalog-search" type="search" placeholder="Search titles" autocomplete="off"></label></div><div class="cards" id="catalog-grid">${collections.map(catalogCard).join('')}</div><p id="catalog-empty" hidden>No collections match. Try another title or category.</p>`;}
function releasePage(id){const c=collections.find(x=>x.id===id);if(!c)return missingPage();return `<a class="text-link" href="#/collection">‹ Back to the collection</a><div class="release-grid"><div class="release-image">${art(c)}<p class="fine-print">Fictional model / decorative artwork · Placeholder imagery</p></div><div>${pageHeading(c.label,c.title,c.description)}<div class="detail-facts"><span>${c.detail}</span><span>On-demand collection</span><span>Sample release</span></div><div class="surface purchase-panel"><p class="eyebrow">YOUR EVENING, YOUR CHOICE</p><div class="detail-price">${c.price===null?'Member access':`$${c.price}`}<small>${c.price===null?'Sample membership benefit':'Illustrative one-time price'}</small></div>${action(c.price===null?'Explore membership':'Preview purchase',c.price===null?'membership':`checkout/${c.id}`)}<button class="outline-control" data-detail-save="${c.id}">${saved.has(c.id)?'Remove from saved':'Save to preview library'}</button><p class="fine-print">No media is uploaded or unlocked in this preview.</p></div><details class="surface"><summary>What is included?</summary><p>${c.type==='photos'?'A curated photographic collection.':'An on-demand film collection.'} Final content, access terms, and availability will be confirmed before launch.</p></details></div></div>`;}
function livePage(){return `${pageHeading('THE LIVE LOUNGE','Meet me <em>after dark.</em>','A little anticipation. A more personal evening.')}<div class="page-tabs" aria-label="Live design states"><button class="active" data-live-state="offline" aria-pressed="true">Offline view</button><button data-live-state="live" aria-pressed="false">Live layout demo</button></div><p class="fine-print">These controls switch design states; no broadcast is taking place.</p><div class="lounge-grid"><div><div class="broadcast-stage" id="broadcast-stage"><span class="broadcast-badge">OFFLINE</span><div class="stage-message"><span class="stage-gem">◇</span><p class="eyebrow">YOUR NEXT EVENING STARTS HERE</p><h2>Worth the wait.</h2><p>Next appearance to be announced.</p></div></div><div class="surface lounge-schedule"><div><p class="eyebrow">NEXT APPEARANCE</p><h3>An evening with Jamie JustiXXX</h3><p>Schedule coming soon · Time zone shown when announced</p></div>${action('Explore membership','membership')}</div><div class="surface"><h3>A seat in the lounge.</h3><p>Live access and any separate ticket options will be displayed before each appearance. Membership inclusions will be clearly marked.</p></div></div><aside class="surface chat-panel"><div class="chat-title"><h3>Lounge conversation</h3><span>PREVIEW</span></div><div class="chat-messages" id="chat-messages" aria-live="polite"><p class="chat-bubble"><strong>The lounge</strong>Welcome. Conversation opens when a live appearance begins.</p></div><div id="chat-composer"><p class="fine-print">Chat is closed while offline.</p>${action('Sign-in preview','signin')}</div></aside></div>`;}
function membershipPage(){return `${pageHeading('YOUR PLACE ON THE INSIDE','Make it <em>your kind of night.</em>','A closer connection. A collection to return to. A place that feels like yours.')}<div class="membership-page-grid"><div class="membership-editorial"><div class="editorial-portrait" role="img" aria-label="Fictional adult fashion model in a plum evening dress"></div><div class="benefit-grid"><div class="surface"><span>01</span><h3>The member collection</h3><p>Browse releases designated for membership.</p></div><div class="surface"><span>02</span><h3>Stay in the know</h3><p>Discover new releases and upcoming appearances.</p></div></div></div><div><div class="membership-card"><p class="eyebrow">THE PLATINUM MEMBERSHIP</p><span class="card-gem">◇</span><div class="price">$24<span> / month</span></div><p>Illustrative price · Not available to purchase</p><ul><li>Access to designated member collections</li><li>New releases in the member feed</li><li>Updates on live appearances</li><li>Membership controls in your account</li></ul>${action('Preview joining','checkout/membership')}<p>Individual releases and live tickets may be sold separately.</p></div><details class="surface" open><summary>Are all collections included?</summary><p>Only releases marked for members. Individual purchases and event tickets will be labeled separately.</p></details><details class="surface"><summary>How will renewal work?</summary><p>The final checkout will disclose recurring charges, renewal timing, and cancellation terms. Billing is not connected in this preview.</p></details></div></div>`;}
function libraryPage(){const list=collections.filter(c=>saved.has(c.id));return `${pageHeading('YOUR PERSONAL SPACE','An evening, <em>kept close.</em>','Your saved previews, purchases, and member collections in one place.')}<div class="page-tabs" aria-label="Library views"><button class="active" data-library-tab="saved" aria-pressed="true">Saved previews <span>${list.length}</span></button><button data-library-tab="purchases" aria-pressed="false">Purchases</button><button data-library-tab="members" aria-pressed="false">Member access</button></div><div id="library-content">${list.length?`<div class="cards">${list.map(catalogCard).join('')}</div>`:`<div class="surface empty-state"><span class="stage-gem">◇</span><h2>Your collection starts here.</h2><p>Save a collection to see it here. Saved previews stay in this browser.</p>${action('Explore the collection','collection')}</div>`}</div>`;}
function accountPage(){return `${pageHeading('YOUR ACCOUNT','Everything, <em>at your pace.</em>','A preview of your personal account. No customer account has been created.')}<div class="account-grid"><aside class="surface account-menu"><span class="avatar-mark">◇</span><h3>Preview member</h3><p>Account design</p><a href="#/library">My library ›</a><a href="#/membership">Membership ›</a><a href="#/verify">Age verification ›</a><a href="#/support">Help & support ›</a></aside><div class="account-panels"><section class="surface"><div class="panel-top"><h2>Profile</h2><span class="status-chip">PREVIEW</span></div><div class="display-field"><span>Display name</span><strong>Preview member</strong></div><div class="display-field"><span>Email address</span><strong>Not connected</strong></div>${action('View sign-in design','signin')}</section><section class="surface"><h2>Membership & billing</h2><div class="display-field"><span>Membership</span><strong>No active subscription</strong></div><div class="display-field"><span>Payment method</span><strong>No payment method stored</strong></div>${action('Explore plans','membership')}${action('Preview member controls','manage-membership')}<button class="outline-control" data-billing-preview>View billing history</button></section><section class="surface"><h2>Privacy & access</h2><p>Age verification has not been completed. The entry screen records only a self-declaration.</p>${action('View age-check journey','verify')}<button class="outline-control" data-clear-saved>Clear saved previews</button><p class="fine-print">Clearing removes only the saved collection list from this browser.</p></section></div></div>`;}
let sampleRenewalOff = false;
function manageMembershipPage(){return `${pageHeading('MEMBER CONTROLS','Your membership.<br><em>Your choice.</em>','Sample account state for visual review. You have no real subscription.')}<div class="checkout-grid"><div><section class="surface"><div class="panel-top"><h2>The Platinum Membership</h2><span class="status-chip">${sampleRenewalOff?'RENEWAL OFF · DEMO':'ACTIVE LAYOUT · DEMO'}</span></div><div class="display-field"><span>Illustrative plan</span><strong>$24 / month</strong></div><div class="display-field"><span>Current access</span><strong>Sample billing period</strong></div><div class="display-field"><span>Next renewal</span><strong>${sampleRenewalOff?'No renewal in this demonstration':'Date supplied by billing provider'}</strong></div><p>${sampleRenewalOff?'This demonstrates a membership that continues to the end of a paid period without renewing. No subscription has actually been cancelled.':'The live account will display the actual renewal date, recurring charge, and cancellation controls.'}</p>${action('View member library','library')}<button class="outline-control" data-manage-renewal>${sampleRenewalOff?'Reset active-member preview':'Preview cancellation'}</button></section><section class="surface"><h2>Payment & receipts</h2><div class="display-field"><span>Payment method</span><strong>Provider-managed payment details</strong></div><p>Billing records and payment updates will open through the selected payment service. No card data is entered in this preview.</p><button class="outline-control" data-payment-preview>Preview payment update</button><button class="outline-control" data-billing-preview>View billing history</button></section></div><aside class="surface"><p class="eyebrow">ALWAYS CLEAR</p><h2>Access at your pace.</h2><p>The final cancellation screen will explain when access ends and whether another charge is scheduled before the customer confirms.</p><p>Renewal, cancellation, and refund terms are provisional until the billing platform and final policies are approved.</p>${action('Help & support','support')}<a class="text-link" href="#/account">Back to account ›</a></aside></div>`;}
function authPage(signup=false){return `<div class="auth-grid"><div class="auth-art"><p class="eyebrow">PLATINUM AFTER DARK</p><h2>A world<br><em>of your own.</em></h2></div><div class="surface auth-panel">${pageHeading(signup?'YOUR INVITATION':'WELCOME BACK',signup?'A little closer.':'Your evening awaits.','Account interface preview. Please do not enter personal information.')}<div class="mock-field"><span>Email address</span><div>your email will appear here</div></div><div class="mock-field"><span>Password</span><div>••••••••••••</div></div>${signup?'<p class="fine-print">The final form will request agreement to the published Terms and Privacy Policy. This preview creates no account.</p>':'<button class="text-link outline-control" data-reset-preview>Forgot password?</button>'}${action(signup?'Preview account view':'Preview signing in','account')}<p>${signup?'Already have an account?':'New to the collection?'} <a class="text-link" href="#/${signup?'signin':'signup'}">${signup?'Sign in':'Create account'}</a></p><p class="fine-print">Authentication and password recovery are not connected.</p></div></div>`;}
function selectedOrder(id){return id==='membership'?{id:'membership',title:'The Platinum Membership',price:24,detail:'Monthly membership · Illustrative recurring price'}:collections.find(c=>c.id===id)||null;}
function checkoutPage(id){const order=selectedOrder(id);if(!order)return missingPage();return `${pageHeading('YOUR NEXT CHAPTER','A thoughtful <em>little indulgence.</em>','Checkout design preview. No transaction can be placed.')}<div class="checkout-grid"><div><section class="surface"><p class="eyebrow">01 · ACCOUNT</p><h2>Your personal access.</h2><p>Sign in or create an account before purchasing.</p>${action('View sign-in','signin')}</section><section class="surface"><p class="eyebrow">02 · ADULT ACCESS</p><h2>Private age assurance.</h2><p>A provider will confirm eligibility where required before restricted content is accessible.</p>${action('View verification design','verify')}</section><section class="surface"><p class="eyebrow">03 · PAYMENT</p><h2>Your payment, protected.</h2><div class="payment-placeholder"><span aria-hidden="true">◇</span><p>Secure payment form will appear here.</p><small>Provider not selected · No card information collected</small></div></section></div><aside class="surface order-summary"><p class="eyebrow">YOUR SELECTION</p><h2>${order.title}</h2><p>${order.detail}</p><div class="summary-line"><span>Sample ${id==='membership'?'monthly price':'price'}</span><strong>$${order.price}</strong></div><div class="summary-line"><span>Taxes / final total</span><span>At live checkout</span></div>${id==='membership'?'<p class="fine-print">The live checkout must display recurring billing consent, renewal timing, and cancellation terms before payment.</p>':''}${action('View confirmation design',`confirmation/${order.id}`)}<p class="fine-print">This button opens another design screen. It does not charge you or create an order.</p></aside></div>`;}
function confirmationPage(id){const order=selectedOrder(id);if(!order)return missingPage();return `<div class="surface confirmation-panel"><span class="stage-gem">◇</span>${pageHeading('CONFIRMATION DESIGN','Your evening <em>starts here.</em>','This is a preview of the post-purchase screen. No payment, order, membership, or content access has been created.')}<div class="display-field"><span>Sample selection</span><strong>${order.title}</strong></div><p>The live version will display the order reference, receipt, and access details after a confirmed payment.</p><div class="page-actions">${action('View library design','library')}${action('Return to collection','collection')}</div></div>`;}
function verificationPage(){return `${pageHeading('ADULT ACCESS','A private check.<br><em>A personal experience.</em>','Age verification journey preview. No checks or document uploads take place here.')}<div class="verify-grid"><div class="surface"><div class="steps"><span>01 · Choose a method</span><span>02 · Provider check</span><span>03 · Return securely</span></div><h2>Choose how to continue.</h2><p>Available methods will depend on the chosen provider and your location.</p><button class="method-card" data-method="selfie"><span>◉</span><div><strong>Selfie age estimation</strong><small>Camera-based estimation with a fallback where needed.</small></div><span>›</span></button><button class="method-card" data-method="document"><span>▤</span><div><strong>Identity document check</strong><small>Check directly with the verification provider.</small></div><span>›</span></button><button class="method-card" data-method="reusable"><span>◇</span><div><strong>Reusable proof of age</strong><small>Where supported by the selected provider.</small></div><span>›</span></button><p class="fine-print">No camera, ID, name, date of birth, or verification data is collected by this preview.</p></div><aside class="surface"><p class="eyebrow">PRIVACY BY DESIGN</p><h2>Only what is needed.</h2><p>Our intended setup asks a specialist provider for an age eligibility result, rather than collecting identity documents in this website.</p><p>Final methods, data sharing, retention, and recheck rules will be explained before a real check starts.</p><span class="status-chip">NOT VERIFIED</span><p>Clicking “I am 18” on entry is self-declaration, not verified-age status.</p><a class="text-link" href="#/support">Need help? ›</a></aside></div>`;}
function aboutPage(){return `${pageHeading('MEET Jamie JustiXXX','The person<br><em>behind the invitation.</em>','A personal space for collections, conversation, and evenings after dark.')}<div class="about-grid"><div class="editorial-portrait" role="img" aria-label="Fictional adult model placeholder; not Jamie JustiXXX"></div><div class="surface"><p class="eyebrow">A NOTE FROM Jamie JustiXXX</p><h2>A little mystery.<br>A little more me.</h2><p>This is where Jamie JustiXXX’s approved introduction will live: her style, what she loves creating, and what visitors can expect from her space.</p><p class="fine-print">Biography pending approval. The pictured fictional model is a temporary layout placeholder.</p>${action('Explore the collection','collection')}${action('Visit the lounge','live')}</div></div>`;}
function infoPage(kind){const data={privacy:['Your privacy. Your space.','This design preview stores saved collection identifiers in localStorage and an age self-declaration in sessionStorage. Neither is proof of purchase or verified age. No account, payment, age verification, or customer support service is connected.','Before launch, the final privacy notice will identify the operator, providers, purposes, retention periods, sharing, and applicable privacy rights.'],terms:['A clear understanding.','All collections, prices, benefits, and interface states are illustrative. No purchases, subscriptions, live access, or service promises are offered through this prototype.','Final purchase, renewal, cancellation, acceptable-use, and access terms require approval before commercial launch.'],support:['A little help, when you need it.','Explore common questions below. Customer support contact details will be added before launch.','This preview does not send messages or create support tickets.']}[kind];return `${pageHeading(kind==='support'?'HERE TO HELP':'THE DETAILS',data[0],data[1])}<div class="surface readable"><p>${data[2]}</p>${kind==='support'?`<details open><summary>Where is my purchase?</summary><p>No orders can be placed in this preview. The live service will show confirmed purchases in My Library.</p></details><details><summary>How do I manage membership?</summary><p>The planned account screen includes membership and billing controls.</p></details><details><summary>Why do I need an age check?</summary><p>Age assurance controls access to age-restricted content. The live check and privacy information will depend on the provider and served location.</p></details><div class="page-actions">${action('My account','account')}${action('Age-check preview','verify')}</div>`:''}<a class="text-link" href="#/home">Return home ›</a></div>`;}
function missingPage(){return `${pageHeading('A DIFFERENT TURN','This page is not here.','Return to the collection to find your next evening.')}${action('Explore the collection','collection')}`;}
function rewriteHomeLinks(){pageMain.querySelectorAll('a[href="#collection"]').forEach(a=>a.href='#/collection');pageMain.querySelectorAll('a[href="#membership"]').forEach(a=>a.href='#/membership');}
function routePage(){const route=location.hash.startsWith('#/')?location.hash.slice(2).split('/'):['home'];const [page,id]=route;modal.close();let html='';switch(page){case 'home':html=homeTemplate;break;case 'collection':html=catalog();break;case 'release':html=releasePage(id);break;case 'live':html=livePage();break;case 'membership':html=membershipPage();break;case 'library':html=libraryPage();break;case 'account':html=accountPage();break;case 'manage-membership':html=manageMembershipPage();break;case 'signin':html=authPage();break;case 'signup':html=authPage(true);break;case 'checkout':html=checkoutPage(id);break;case 'confirmation':html=confirmationPage(id);break;case 'verify':html=verificationPage();break;case 'about':html=aboutPage();break;case 'privacy':case 'terms':case 'support':html=infoPage(page);break;default:html=missingPage();}
pageMain.className=page==='home'?'':'page-shell';pageMain.innerHTML=page==='home'?html:html+pageNotice;if(page==='home'){render();rewriteHomeLinks();}document.title=`${pageTitles[page]||'Collection'} — Platinum After Dark`;document.querySelectorAll('nav a').forEach(a=>{const active=a.hash===`#/${page}`;a.classList.toggle('is-active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(!document.querySelector('#site-content').hidden){window.scrollTo({top:0,behavior:'instant'});const heading=pageMain.querySelector('h1,h2');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}}}
// Replace homepage-only navigation with persistent destination links.
document.querySelector('nav').innerHTML=Object.entries({home:'Home',collection:'The Collection',live:'Live Lounge',membership:'Membership',about:'About Jamie'}).map(([id,label])=>`<a href="#/${id}">${label}</a>`).join('');
document.querySelectorAll('.brand').forEach(a=>a.href='#/home');
const accountLink=document.createElement('a');accountLink.href='#/account';accountLink.className='text-link account-link';accountLink.textContent='My Account';document.querySelector('header').append(accountLink);
let currentCategory='all';
function filterCatalog(){const q=(document.querySelector('#catalog-search')?.value||'').trim().toLowerCase();const visible=collections.filter(c=>(currentCategory==='all'||c.type===currentCategory)&&c.title.toLowerCase().includes(q));document.querySelector('#catalog-grid').innerHTML=visible.map(catalogCard).join('');document.querySelector('#catalog-empty').hidden=visible.length>0;}
document.addEventListener('input',e=>{if(e.target.id==='catalog-search')filterCatalog();});
document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;
if(button.dataset.catalogFilter){currentCategory=button.dataset.catalogFilter;document.querySelectorAll('[data-catalog-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});filterCatalog();}
if(button.dataset.detailSave){const id=button.dataset.detailSave;saved.has(id)?saved.delete(id):saved.add(id);try{localStorage.setItem('pad-saved',JSON.stringify([...saved]));}catch{}updateCount();button.textContent=saved.has(id)?'Remove from saved':'Save to preview library';}
if(button.dataset.liveState){const live=button.dataset.liveState==='live';document.querySelectorAll('[data-live-state]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});document.querySelector('#broadcast-stage').innerHTML=live?'<span class="broadcast-badge">LIVE LAYOUT DEMO · NO BROADCAST</span><div class="stage-message"><span class="stage-gem">▷</span><h2>The live experience.</h2><p>Video playback and event controls will appear here.</p></div><div class="player-controls"><span>00:00 / —</span><span>Audio · Quality · Fullscreen</span></div>':'<span class="broadcast-badge">OFFLINE</span><div class="stage-message"><span class="stage-gem">◇</span><h2>Worth the wait.</h2><p>Next appearance to be announced.</p></div>';document.querySelector('#chat-composer').innerHTML=live?'<label for="demo-message">Try a preview message</label><div class="chat-input"><input id="demo-message" maxlength="180" placeholder="Message stays on this page"><button class="outline-control" data-chat-send>Send</button></div><small>Local visual demonstration only.</small>':'<p class="fine-print">Chat is closed while offline.</p><a class="text-link" href="#/signin">Sign-in preview ›</a>';}
if(button.hasAttribute('data-chat-send')){const input=document.querySelector('#demo-message');if(input.value.trim()){const bubble=document.createElement('p');bubble.className='chat-bubble';const who=document.createElement('strong');who.textContent='You · local preview';bubble.append(who,document.createTextNode(input.value.trim()));document.querySelector('#chat-messages').append(bubble);input.value='';bubble.scrollIntoView({block:'nearest'});}}
if(button.dataset.libraryTab){const tab=button.dataset.libraryTab;if(tab==='saved'){routePage();return;}document.querySelectorAll('[data-library-tab]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});document.querySelector('#library-content').innerHTML=`<div class="surface empty-state"><span class="stage-gem">◇</span><h2>${tab==='purchases'?'A place for every purchase.':'Your membership, in view.'}</h2><p>${tab==='purchases'?'No purchases have been made. Confirmed purchases will appear here.':'There is no active membership in this preview.'}</p>${action(tab==='purchases'?'Browse collections':'Explore membership',tab==='purchases'?'collection':'membership')}</div>`;}
if(button.hasAttribute('data-manage-renewal')){if(sampleRenewalOff){sampleRenewalOff=false;routePage();}else{open('<p class="eyebrow">CANCELLATION DESIGN PREVIEW</p><h2>A pause, on your terms.</h2><p>In the live service, this screen will show the exact final access date and any remaining charges before cancellation.</p><p>This only changes a sample membership state. It does not cancel a real subscription.</p><div class="page-actions"><button class="button platinum" data-confirm-demo-cancel>Show renewal-off design</button><button class="outline-control" data-keep-demo>Keep active design</button></div>');}}
if(button.hasAttribute('data-confirm-demo-cancel')){sampleRenewalOff=true;routePage();}
if(button.hasAttribute('data-keep-demo'))modal.close();
if(button.hasAttribute('data-payment-preview'))open('<h2>Payment update preview</h2><p>The live version will open a secure payment-provider form. This site will not ask for card information in a general text field.</p><p>No payment details have been collected or changed.</p>');
if(button.hasAttribute('data-billing-preview'))open('<h2>Billing history</h2><p>No transactions or subscriptions exist in this preview. Confirmed charges, receipts, and renewal details will appear here after the payment platform is connected.</p>');
if(button.hasAttribute('data-reset-preview'))open('<h2>A fresh start.</h2><p>The live password reset screen will send a recovery link through the account provider. No emails are collected or sent by this prototype.</p>');
if(button.hasAttribute('data-clear-saved')){saved.clear();try{localStorage.removeItem('pad-saved');}catch{}updateCount();open('<h2>Saved previews cleared.</h2><p>The saved collection list was removed from this browser. No customer purchases or subscriptions were changed.</p>');}
if(button.dataset.method)open('<p class="eyebrow">VERIFICATION JOURNEY PREVIEW</p><h2>Your check stays private.</h2><p>The live version will hand you to the selected age-assurance provider, explain its privacy terms, and return an eligibility result securely.</p><p>No camera, identity document, or personal data has been requested. This demonstration does not verify your age.</p>');
});
window.addEventListener('hashchange',()=>{currentCategory='all';routePage();});routePage();
